    18	async function runSources() {
    19	  console.log('[ingestion] Running source scrapers...');
    20	  
    21	  // Stockholm venues are ALWAYS first - highest priority city
    22	  // Malmö Live is also prioritized (local Swedish venue)
    23	  const sources = [
    24	    { name: 'stockholm-venues', fn: scrapeStockholm, priority: 1 },
    25	    { name: 'malmolive', fn: scrapeMalmolive, priority: 2 },
    26	    { name: 'ticketmaster', fn: scrapeTicketmaster, priority: 3 },
    27	    { name: 'eventbrite', fn: scrapeEventbrite, priority: 4 },
    28	    { name: 'billetto', fn: scrapeBilletto, priority: 5 },
    29	  ];
    30	  
    31	  // Sort by priority (Stockholm first)
    32	  sources.sort((a, b) => a.priority - b.priority);
    33	  console.log(`[ingestion] Source order: ${sources.map(s => s.name).join(', ')}`);
    34	
    35	  const results = await Promise.allSettled(
    36	    sources.map((s) => s.fn())
    37	  );
    38	
    39	  // Detailed status reporting per source
    40	  let successCount = 0;
    41	  let failCount = 0;
    42	  let skipCount = 0;
    43	  
    44	  sources.forEach((s, i) => {
    45	    if (results[i].status === 'fulfilled') {
    46	      const status = results[i].value;
    47	      if (status === 'skipped') {
    48	        skipCount++;
    49	        console.log(`[ingestion] ⏭️ ${s.name} skipped`);
    50	      } else {
    51	        successCount++;
    52	        console.log(`[ingestion] ✅ ${s.name} completed`);
    53	      }
    54	    } else {
    55	      failCount++;
    56	      const reason = (results[i] as PromiseRejectedResult).reason;
    57	      console.error(`[ingestion] ❌ ${s.name} failed: ${reason?.message || reason}`);
    58	    }
    59	  });
    60	
    61	  console.log(`[ingestion] Summary: ${successCount} succeeded, ${skipCount} skipped, ${failCount} failed`);
    62	
    63	  // Fetch next batch of expansion candidates from the queue
    64	  const candidates = await fetchNextExpansionCandidates(5);
    65	  if (candidates.length > 0) {
    66	    console.log('[ingestion] Next expansion candidates:');
    67	    for (const c of candidates) {
    68	      console.log(`  - ${c.candidate_name} (${c.city}) priority=${c.priority_score}`);
    69	    }
    70	
    71	    // Process expansion batch - this creates results in discovery_expansion_results
    72	    await processExpansionBatch(5);
    73	  }
    74	}
    75	
    76	function startNormalizerWorker() {
    77	  const worker = createNormalizerWorker(processRawEvent);
    78	
    79	  worker.on('completed', (job) => {
    80	    console.log(`[normalizer] Job ${job.id} completed`);
    81	  });
    82	
    83	  worker.on('failed', (job, err) => {
    84	    console.error(`[normalizer] Job ${job?.id} failed:`, err.message);
    85	  });
    86	
    87	  console.log('[normalizer] Worker started');
    88	  return worker;
    89	}
