    91	async function main() {
    92	  console.log('[ingestion] EventPulse ingestion service starting...');
    93	
    94	  // Initialize Meilisearch index settings (if configured)
    95	  await initSearchIndex();
    96	
    97	  // Seed Stockholm venues for discovery ranking
    98	  console.log('[ingestion] Seeding Stockholm venues...');
    99	  const seededCount = await seedStockholmVenues();
   100	  console.log(`[ingestion] Seeded ${seededCount} Stockholm venues`);
   101	
   102	  // Show seed status
   103	  const status = await getSeedStatus();
   104	  console.log(`[ingestion] Discovery status: ${status.total} total, ${status.stockholm} Stockholm, ${status.seeded} seeded`);
   105	
   106	  // Start the normalizer worker
   107	  startNormalizerWorker();
   108	
   109	  // Start the search sync worker (only if Meilisearch is configured)
   110	  if (isMeilisearchConfigured()) {
   111	    startSearchWorker();
   112	  } else {
   113	    console.warn('[ingestion] Meilisearch not configured, search worker disabled');
   114	  }
   115	
   116	  // Run immediately on startup
   117	  await runSources();
   118	
   119	  // Schedule: every 30 minutes
   120	  cron.schedule('*/30 * * * *', async () => {
   121	    await runSources();
   122	  });
   123	
   124	  console.log('[ingestion] Scheduler running. Scraping every 30 minutes.');
   125	
