   128	    const stats = await getQueueStats();
   129	    console.log(`[ingestion] Expansion queue: ${stats.pending} pending, ${stats.processing} processing, ${stats.expanded} expanded`);
   130	  }, 5 * 60 * 1000); // Every 5 minutes
